head.script:
scwin.onpageload = function () { };
scwin.trigger1_onclick = function (e) { grd.advancedExcelDownload({ "useStyle": "true" }, {}); };
scwin.trigger2_onclick = function (e) { $c.data.uploadGridViewExcel(grd_Excel, { "sheetNo": 2, "startRowIndex": 6, "startColumnIndex": 1 }); };
scwin.trigger3_onclick = function (e) { $p.executeSubmission("sub1"); };
scwin.trigger4_onclick = function (e) { dataList.removeAll(); };
scwin.dlt_Excel_ondataload = function () { dataList.setJSON(dlt_Excel.getAllJSON(), true); dlt_Excel.setJSON([]); };
scwin.trigger5_onclick = function (e) { $c.data.uploadGridViewExcel(grd, { "startRowIndex": 3, "append": "1" }); };

scwin.dataList_ondataload = function () {
    inp_grd_cnt.setValue(WebSquare.util.setNumber(dataList.getRowCount()));
};

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#grd_customFilter_list_input', 'key-sequence', {
			sequence: '1'
		});
	}

	scwin.setSimulate2 = function() {
		scwin.simulateWrapper('#grd_customFilter_list_input', 'key-sequence', {
			sequence: '4'
		});
	}

	scwin.setSimulate3 = function() {
		scwin.simulateWrapper('#grd_customFilter_list_input', 'key-sequence', {
			sequence: '9'
		});
	}	
        scwin.checkBeforeTime = function(){
		date = new Date();
		min = date.getMinutes();
		sec = date.getSeconds();
		milisec = date.getMilliseconds();
		before = (min*60 + sec)*1000 + milisec;
		console.log('before :' + before)
        }

        scwin.checkAfterTime = function(){
		date = new Date();
		min = date.getMinutes();
		sec = date.getSeconds();
		milisec = date.getMilliseconds();
		after = (min*60 + sec)*1000 + milisec;
		console.log('after :' + after)		
        }

        scwin.compareTime = function(){
		console.log(Math.abs(after - before))
		return Math.abs(after - before) <= 1200;
        }

	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");

		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_column71_filter').click()");


		WebSquare.wUnit.addCommand("set", "scwin.checkBeforeTime()");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");		
		WebSquare.wUnit.addCommand("set", "scwin.checkAfterTime()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("assert", "scwin.compareTime()","true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
        }
	scwin.unitTest()
